#include <vector>
#include <cstddef>
#include <cmath>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Uses a parallel Jacobi iterative method with OpenMP.
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    // Ensure output size
    x.assign(N, 0.0);
    if (N == 0) return;

    // Build row-wise COO buckets and extract diagonal entries.
    std::vector<std::vector<std::pair<size_t, double>>> rows(N);
    std::vector<double> diag(N, 0.0);

    for (const auto& e : A) {
        if (e.row < N && e.column < N) {
            rows[e.row].push_back({e.column, e.value});
            if (e.row == e.column) {
                diag[e.row] += e.value; // handle possible duplicate diagonal entries
            }
        }
    }

    // If b size is smaller than N, treat missing entries as 0.
    std::vector<double> rhs(N, 0.0);
    for (size_t i = 0; i < N && i < b.size(); ++i) rhs[i] = b[i];

    // Jacobi iteration buffers
    std::vector<double> x_old(N, 0.0), x_new(N, 0.0);

    const size_t maxIters = 10000;
    const double tol = 1e-10;

    for (size_t iter = 0; iter < maxIters; ++iter) {
        double maxDiff = 0.0;

        #pragma omp parallel for reduction(max:maxDiff)
        for (ptrdiff_t i = 0; i < static_cast<ptrdiff_t>(N); ++i) {
            const double di = diag[static_cast<size_t>(i)];
            if (std::abs(di) < 1e-18) {
                // No usable diagonal term; keep current value to avoid division by zero.
                x_new[static_cast<size_t>(i)] = x_old[static_cast<size_t>(i)];
            } else {
                double sigma = 0.0;
                for (const auto& cv : rows[static_cast<size_t>(i)]) {
                    size_t j = cv.first;
                    double aij = cv.second;
                    if (j != static_cast<size_t>(i)) {
                        sigma += aij * x_old[j];
                    }
                }
                x_new[static_cast<size_t>(i)] = (rhs[static_cast<size_t>(i)] - sigma) / di;
            }

            double d = std::abs(x_new[static_cast<size_t>(i)] - x_old[static_cast<size_t>(i)]);
            if (d > maxDiff) maxDiff = d;
        }

        x_old.swap(x_new);

        if (maxDiff < tol) break;
    }

    x = x_old;
}
